const fs = require('node:fs');
const path = require('node:path');
const { spawnSync } = require('node:child_process');
const mount = process.argv[1];
if (!fs.lstatSync(mount).isDirectory()) throw new Error('workspace must be an ordinary directory');
const imports = fs.readdirSync(mount, { withFileTypes: true }).filter(entry => /^boxwarden-import-[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(entry.name));
if (imports.length !== 1 || !imports[0].isDirectory()) throw new Error('edit-project requires exactly one ordinary synthetic import directory');
const app = path.join(mount, imports[0].name, 'app.js');
const info = fs.lstatSync(app);
if (!info.isFile() || info.nlink !== 1) throw new Error('synthetic app must be an ordinary unlinked file');
const result = spawnSync(process.execPath, [app, '--edit'], { stdio: 'inherit' });
if (result.error) throw result.error;
process.exit(result.status === null ? 1 : result.status);
